def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # A diagonal run of two or more equal non-background cells extends at both ends.
    for color in {v for row in grid for v in row if v != bg}:
        for dr, dc in ((1, 1), (1, -1)):
            starts = []
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    pr, pc = r-dr, c-dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                        continue
                    length = 1
                    rr, cc = r+dr, c+dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        length += 1; rr += dr; cc += dc
                    if length >= 2:
                        # Extend from both endpoints through background; preserve all existing cells.
                        for sr, sc, vr, vc in ((r-dr, c-dc, -dr, -dc), (rr, cc, dr, dc)):
                            while 0 <= sr < h and 0 <= sc < w:
                                if out[sr][sc] != bg:
                                    break
                                out[sr][sc] = color
                                sr += vr; sc += vc
    return out
